mapper.select:
select id, status
from cmdb_sync_audit
where id = #{value}

select a.id, a.ci_collection_id AS ciCollectionId, b.collection_name AS ciCollectionName, a.start_time AS startTime, a.end_time AS endTime, (UNIX_TIMESTAMP(IFNULL(end_time, NOW(3)))*1000 - UNIX_TIMESTAMP(start_time)*1000) AS timeCost, a.input_from AS inputFrom, a.status, a.transaction_group_id AS transactionGroupId, a.server_id AS serverId, (select count(1) from cmdb_sync_data_audit x where x.audit_id = a.id) as errorDataCount, a.data_count AS dataCount, a.error AS error from cmdb_sync_audit a join cmdb_sync_ci_collection b on a.ci_collection_id = b.id
order by id desc
limit #{startNum}, #{pageSize}

mapper.update:
UPDATE
    cmdb_sync_audit
SET data_count      = #{dataCount},
    current_data_id = #{currentDataId}
WHERE id = #{id}

UPDATE
    cmdb_sync_audit
SET status = #{status}
where id = #{id}

UPDATE
cmdb_sync_audit
SET
end_time = NOW(3),
status = #{status}

    ,data_count = #{dataCount}


    ,error = #{error,typeHandler=CompressHandler}

WHERE id = #{id}

mapper.delete:
delete
from cmdb_sync_data_audit
where data_id = #{dataId}
  and ci_collection_id = #{ciCollectionId}

delete
from cmdb_sync_data_hash
where data_id = #{dataId}
  and collection_name = #{collectionName}
